import{_ as o,r as a,o as l,c,e as t,a as p,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Поле Checkbox List - October CMS - 3.x","titleTemplate":false,"description":"Поле формы","frontmatter":{"subtitle":"Поле формы","shortname":"Checkbox List"},"headers":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}],"relativePath":"3.x/ru/element/form/field-checkboxlist.md","filePath":"3.x/ru/element/form/field-checkboxlist.md"}'),d={name:"3.x/ru/element/form/field-checkboxlist.md"};function i(u,s,k,m,h,g){const n=a("pre-heading"),e=a("post-heading");return l(),c("div",null,[t(n),s[0]||(s[0]=p("h1",null,"Поле Checkbox List",-1)),t(e),s[1]||(s[1]=r(`<p>Поле <code>checkboxlist</code> рендерит список чекбоксов. Списки чекбоксов поддерживают те же методы определения опций, что и <a href="./field-dropdown.html">тип поля dropdown</a>, а также поддерживают вторичные описания, представленные в <a href="./field-radio.html">типе поля radio</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Permissions
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkboxlist
    <span class="token key atrule">options</span><span class="token punctuation">:</span>
        <span class="token key atrule">open_account</span><span class="token punctuation">:</span> Open account
        <span class="token key atrule">close_account</span><span class="token punctuation">:</span> Close account
        <span class="token key atrule">modify_account</span><span class="token punctuation">:</span> Modify account
</code></pre></div><p>Поддерживаются и обычно используются следующие <a href="./../form-fields.html">свойства поля</a>.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя при отображении поля формы пользователю.</td></tr><tr><td><strong>options</strong></td><td>доступные опции для списка, как массив.</td></tr><tr><td><strong>optionsMethod</strong></td><td>получает опции из метода, определённого в модели или как статический метод, например <code>Class::method</code>.</td></tr><tr><td><strong>default</strong></td><td>значение по умолчанию для новых записей.</td></tr><tr><td><strong>quickselect</strong></td><td>показывает кнопки быстрого выбора.</td></tr><tr><td><strong>cssClass</strong></td><td>используется для установки опций в строку.</td></tr><tr><td><strong>inlineOptions</strong></td><td>отображает опции рядом друг с другом вместо стопкой, когда менее 10 опций.</td></tr><tr><td><strong>placeholder</strong></td><td>сообщение, отображаемое когда записи не выбраны (контекст предпросмотра).</td></tr><tr><td><strong>cumulative</strong></td><td>при вложенных чекбоксах, установка родительского отмечает все дочерние. По умолчанию: <code>false</code></td></tr></tbody></table></div><p>Вы можете использовать свойство <code>default</code> для установки значения по умолчанию, где значение — ключ опции.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Permissions
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkboxlist
    <span class="token key atrule">default</span><span class="token punctuation">:</span> open_account
</code></pre></div><p>Опции могут отображаться в строку друг с другом вместо отдельных строк, установив свойство <code>inlineOptions</code> в <code>true</code>. Это применяется только когда доступных опций менее 10.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkboxlist
    <span class="token key atrule">inlineOptions</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>Меню быстрого выбора с кнопками «Выбрать все» и «Снять все» станет видимым, когда в списке более 10 элементов. Для явного включения этих кнопок используйте опцию <code>quickselect</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkboxlist
    <span class="token key atrule">quickselect</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>При использовании <a href="./../define-options.html">детализированных опций</a> чекбоксы могут отображаться во вложенной структуре. Установите свойство <code>cumulative</code> в <code>true</code>, если хотите отмечать все дочерние чекбоксы при выборе родительского.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkboxlist
    <span class="token key atrule">cumulative</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../define-options.html">Детализированные определения опций</a></li><li><a href="./field-dropdown.html">Поле формы Dropdown</a></li><li><a href="./field-radio.html">Поле формы Radio</a></li></ul></div>`,14))])}const _=o(d,[["render",i]]);export{f as __pageData,_ as default};
